const f = $('When Executed by Another Workflow').first().json;
const m = n => 'N' + (Number(n) / 1e6).toFixed(2) + 'm';
const price = Number(f.fuel_price || 1250);
const pct = Math.round((price - 1250) / 1250 * 100);
const extra = 2880 * (price - 1250);
const invoices = (f.open_invoices || [])
  .map(i => `- ${i.invoice_id} ${i.client_name}: ${m(i.amount)} due Day ${i.due_day}`)
  .join('\n');

const prompt = `You are a cashflow analyst for BrightPath Logistics, a Nigerian delivery company.
Use ONLY the verified figures below. Do not invent any number, client or date.

VERIFIED FIGURES
- Risk state: ${f.risk_state}
- Lowest projected balance in the next 30 days: ${m(f.minimum_projected_balance)} on Day ${f.day_of_minimum}
- Safety buffer: N4.00m
- Days until the buffer is breached: ${f.days_to_breach}
- Current cash: ${m(f.current_cash)}
- Diesel price: N${price} per litre (normal N1250), a ${pct}% rise, adding ${m(extra)} to each weekly fuel payment of 2,880 litres
- Open invoices:
${invoices}

Return ONLY a JSON object, no markdown, with exactly these keys:
{"summary": "one sentence", "cause": "one sentence", "urgency": "LOW|MEDIUM|HIGH|CRITICAL", "actions": ["action 1", "action 2", "action 3"]}
The three actions must be practical and specific, use the figures and invoices above, and cover three different levers: (1) ask a named client to pay an open invoice early, offering a small early-payment discount, (2) ask Harbour Fuels to split a fuel payment into two instalments, (3) a temporary fuel surcharge on new invoices or a route/fuel-use cut.`;

return [{ json: { prompt } }];

