const base = $('When Executed by Another Workflow').first().json;
const r = $input.first().json;
let a;
if (r.summary) {
  a = r;
} else {
  let text = r.content?.parts?.[0]?.text ?? r.text ?? r.output ?? '';
  if (typeof text !== 'string') text = JSON.stringify(text);
  text = text.replace(/```json|```/g, '').trim();
  try { a = JSON.parse(text); }
  catch (e) { throw new Error('AI returned invalid JSON: ' + text.slice(0, 200)); }
}

const urgencies = ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];
const errs = [];
if (!a.summary || typeof a.summary !== 'string') errs.push('summary missing');
if (!a.cause || typeof a.cause !== 'string') errs.push('cause missing');
if (!urgencies.includes(String(a.urgency).toUpperCase())) errs.push('urgency invalid');
if (!Array.isArray(a.actions) || a.actions.length !== 3 ||
    a.actions.some(x => typeof x !== 'string' || !x.trim()))
  errs.push('actions must be exactly 3 non-empty strings');
if (errs.length) throw new Error('AI output failed validation: ' + errs.join('; '));

return [{ json: {
  company_id: base.company_id,
  run_id: base.run_id,
  risk_state: base.risk_state,
  summary: a.summary,
  cause: a.cause,
  urgency: String(a.urgency).toUpperCase(),
  actions: a.actions,
  ai_source: 'gemini'
}}];
